import { MakeLogicType, afterMount, connect, kea, key, path, props, reducers } from 'kea'
import { loaders } from 'kea-loaders'

import { teamLogic } from 'scenes/teamLogic'

import { propertyDefinitionsValueCountsRetrieve } from '~/generated/core/api'
import type { PropertyUsageEntryApi, PropertyValueCountsResponseApi } from '~/generated/core/api.schemas'

export interface PropertyValueCountsLogicProps {
    entry: PropertyUsageEntryApi
}

// Generated by kea-typegen. Update if you're an agent, ignore if you're human.
export interface propertyValueCountsLogicValues {
    currentProjectId: number | string // teamLogic
    valueCounts: PropertyValueCountsResponseApi | null
    valueCountsFailed: boolean
    valueCountsLoading: boolean
}

// Generated by kea-typegen. Update if you're an agent, ignore if you're human.
export interface propertyValueCountsLogicActions {
    loadValueCounts: () => any
    loadValueCountsFailure: (
        error: string,
        errorObject?: any
    ) => {
        error: string
        errorObject?: any
    }
    loadValueCountsSuccess: (
        valueCounts: PropertyValueCountsResponseApi | null,
        payload?: any
    ) => {
        valueCounts: PropertyValueCountsResponseApi | null
        payload?: any
    }
}

// Generated by kea-typegen. Update if you're an agent, ignore if you're human.
export interface propertyValueCountsLogicMeta {
    key: string
}

export type propertyValueCountsLogicType = MakeLogicType<
    propertyValueCountsLogicValues,
    propertyValueCountsLogicActions,
    PropertyValueCountsLogicProps,
    propertyValueCountsLogicMeta
>

export const propertyValueCountsLogic = kea<propertyValueCountsLogicType>([
    props({} as PropertyValueCountsLogicProps),
    key(({ entry }) => `${entry.type}/${entry.group_type_index ?? ''}/${entry.name}`),
    path((key) => ['scenes', 'data-management', 'definition', 'usage', 'propertyValueCountsLogic', key]),
    connect(() => ({
        values: [teamLogic, ['currentProjectId']],
    })),
    loaders(({ values, props }) => ({
        valueCounts: [
            null as PropertyValueCountsResponseApi | null,
            {
                loadValueCounts: async (): Promise<PropertyValueCountsResponseApi | null> => {
                    return await propertyDefinitionsValueCountsRetrieve(String(values.currentProjectId), props.entry)
                },
            },
        ],
    })),
    reducers({
        valueCountsFailed: [
            false,
            {
                loadValueCounts: () => false,
                loadValueCountsSuccess: () => false,
                loadValueCountsFailure: () => true,
            },
        ],
    }),
    afterMount(({ actions }) => {
        actions.loadValueCounts()
    }),
])
